package com.vision.iptv;
import java.io.*;import java.net.*;import java.util.*;import java.text.*;import java.util.zip.GZIPInputStream;import android.util.Xml;import org.xmlpull.v1.XmlPullParser;
final class Epg {
 static class Programme {String title="",description="";long start,end;}
 final Map<String,List<Programme>> entries=new HashMap<>();
 static long time(String value){if(value==null)return 0;try{String s=value.trim();SimpleDateFormat f=new SimpleDateFormat(s.length()>14?"yyyyMMddHHmmss Z":"yyyyMMddHHmmss",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.parse(s).getTime();}catch(Exception e){return 0;}}
 static File cacheFile(File dir,String address)throws Exception{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(address.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder name=new StringBuilder("epg_");for(byte b:hash)name.append(String.format(Locale.US,"%02x",b&255));return new File(dir,name+".bin");}
 static Epg readCache(File file)throws Exception{if(!file.isFile()||file.length()>48L*1024*1024||System.currentTimeMillis()-file.lastModified()>604800000L)return null;Epg result=new Epg();try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(file)))){if(in.readInt()!=0x45504731)return null;int n=in.readInt();if(n<0||n>300000)throw new IOException("Invalid cache");long now=System.currentTimeMillis();for(int i=0;i<n;i++){String id=in.readUTF();Programme p=new Programme();p.start=in.readLong();p.end=in.readLong();p.title=in.readUTF();p.description=in.readUTF();if(p.end>now-604800000L&&p.start<now+604800000L)result.entries.computeIfAbsent(id,k->new ArrayList<>()).add(p);}}return result;}
 void writeCache(File file)throws Exception{File tmp=File.createTempFile("epg_",".tmp",file.getParentFile());try{try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(tmp)))){out.writeInt(0x45504731);int n=0;for(List<Programme> l:entries.values())n+=l.size();out.writeInt(n);for(Map.Entry<String,List<Programme>> e:entries.entrySet())for(Programme p:e.getValue()){out.writeUTF(e.getKey());out.writeLong(p.start);out.writeLong(p.end);out.writeUTF(p.title.substring(0,Math.min(2000,p.title.length())));out.writeUTF(p.description.substring(0,Math.min(4000,p.description.length())));}}if(tmp.length()>48L*1024*1024)return;if(!tmp.renameTo(file))throw new IOException("Cache rename failed");File[] old=file.getParentFile().listFiles((d,n)->n.startsWith("epg_")&&n.endsWith(".bin")&&!n.equals(file.getName()));if(old!=null)for(File x:old)x.delete();}finally{tmp.delete();}}
 static Epg load(String address)throws Exception{URL url=new URL(address);if(!url.getProtocol().equals("http")&&!url.getProtocol().equals("https"))throw new IOException("HTTP(S) only");HttpURLConnection c=NetworkPolicy.open(url,15000,30000,"VisionIPTV/1.0",false,null);Epg epg=new Epg();try(BufferedInputStream raw=new BufferedInputStream(c.getInputStream())){raw.mark(2);int a=raw.read(),b=raw.read();raw.reset();InputStream in=a==31&&b==139?new GZIPInputStream(raw):raw;XmlPullParser p=Xml.newPullParser();p.setInput(in,null);Programme item=null;String channel=null;long now=System.currentTimeMillis();int count=0;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("programme")){item=new Programme();channel=p.getAttributeValue(null,"channel");item.start=time(p.getAttributeValue(null,"start"));item.end=time(p.getAttributeValue(null,"stop"));}else if(item!=null&&tag.equals("title"))item.title=p.nextText();else if(item!=null&&tag.equals("desc"))item.description=p.nextText();}else if(event==XmlPullParser.END_TAG&&p.getName().equals("programme")&&item!=null){if(channel!=null&&item.end>now-604800000L&&item.start<now+604800000L){epg.entries.computeIfAbsent(channel,k->new ArrayList<>()).add(item);if(++count>300000)throw new IOException("EPG too large");}item=null;}}}finally{c.disconnect();}for(List<Programme> l:epg.entries.values())l.sort(Comparator.comparingLong(x->x.start));return epg;}
 List<Programme> forChannel(String id){return entries.getOrDefault(id,Collections.emptyList());}
 Programme current(String id){long now=System.currentTimeMillis();for(Programme p:forChannel(id))if(p.start<=now&&p.end>now)return p;return null;}
}